// Some portions generated by Claude
import { useCallback, useEffect, useState } from "react";
import type { Binding } from "./explorer-types.ts";
import type { GraphEdge } from "./graph-types.ts";
import type { RdfExplorer } from "./rdf-explorer.ts";
import type { GraphScope } from "./rdf-vocabulary.ts";
import {
  predicateInfo,
  predicateInfoQuery,
  predicateUsageQuery,
  statementAnnotationsQuery,
  statementCards,
  statementTokens,
  type PredicateInfo,
  type StatementCard,
} from "./statement-details.ts";
import { QueryFailure } from "./request-batching.ts";
import { queryRepository } from "./transport.ts";

/** Usage is counted up to this many statements ("10,000+"). */
export const PREDICATE_USAGE_CAP = 10000;

export type StatementDetails = {
  status: "loading" | "ready" | "failed";
  info: PredicateInfo | null;
  uses: { count: number; atLeast: boolean } | null;
  cards: StatementCard[];
  /** A blank node takes part in the statement, so the repository cannot be asked about it. */
  unnamed: boolean;
};

const EMPTY: StatementDetails = { status: "loading", info: null, uses: null, cards: [], unnamed: false };

/** Predicates do not change while the page is open; their information is asked for once per endpoint and scope. */
const predicateCache = new Map<string, Promise<Pick<StatementDetails, "info" | "uses">>>();
/** Endpoints that rejected a triple term `<<( … )>>` in a query; they are asked for classic reifications only. */
const withoutTripleTerms = new Set<string>();

function predicateDetails(endpoint: string, scope: GraphScope, predicate: string) {
  const key = JSON.stringify([endpoint, scope, predicate]);
  let cached = predicateCache.get(key);
  if (!cached) {
    cached = Promise.all([
      queryRepository(endpoint, predicateInfoQuery(predicate, scope)),
      queryRepository(endpoint, predicateUsageQuery(predicate, PREDICATE_USAGE_CAP, scope)),
    ]).then(([info, usage]) => {
      const count = Number.parseInt(usage.results?.bindings?.[0]?.uses?.value ?? "", 10);
      return {
        info: predicateInfo((info.results?.bindings ?? []) as Binding[]),
        uses: Number.isFinite(count)
          ? { count: Math.min(count, PREDICATE_USAGE_CAP), atLeast: count > PREDICATE_USAGE_CAP }
          : null,
      };
    });
    cached.catch(() => predicateCache.delete(key));
    predicateCache.set(key, cached);
  }
  return cached;
}

async function annotations(endpoint: string, scope: GraphScope, edge: GraphEdge, signal: AbortSignal) {
  const tokens = statementTokens(edge);
  if (!tokens) return null;
  if (!withoutTripleTerms.has(endpoint)) {
    try {
      const result = await queryRepository(endpoint, statementAnnotationsQuery(tokens, scope, true), signal);
      return statementCards((result.results?.bindings ?? []) as Binding[]);
    } catch (error) {
      // Only a rejected query means the store does not read triple terms; a timeout or an outage is just an error.
      if (signal.aborted || !(error instanceof QueryFailure) || error.status !== 400) throw error;
      withoutTripleTerms.add(endpoint);
    }
  }
  const result = await queryRepository(endpoint, statementAnnotationsQuery(tokens, scope, false), signal);
  return statementCards((result.results?.bindings ?? []) as Binding[]);
}

/** The IRIs a statement card names, so their labels can be loaded. */
function namedIris(details: StatementDetails) {
  const iris = [
    ...(details.info ? [...details.info.domain, ...details.info.range, ...details.info.superProperties, ...details.info.inverse] : []),
  ];
  for (const card of details.cards) {
    if (card.about.type === "uri") iris.push(card.about.value);
    for (const row of card.rows) {
      iris.push(row.property);
      if (row.value?.type === "uri") iris.push(row.value.value);
    }
  }
  return [...new Set(iris)];
}

/** What the statement card shows for the focused edge, and the labels of the resources it names. */
export function useStatementDetails(edge: GraphEdge | null, endpoint: string, scope: GraphScope, explorer: RdfExplorer) {
  const [details, setDetails] = useState<StatementDetails>(EMPTY);
  const [, setLabelEpoch] = useState(0);
  const edgeKey = edge ? JSON.stringify([edge.source, edge.predicate, edge.target]) : "";

  useEffect(() => {
    if (!edge) return;
    const controller = new AbortController();
    setDetails(EMPTY);
    void (async () => {
      try {
        const [predicate, cards] = await Promise.all([
          predicateDetails(endpoint, scope, edge.predicate),
          annotations(endpoint, scope, edge, controller.signal),
        ]);
        if (controller.signal.aborted) return;
        const next: StatementDetails = { status: "ready", ...predicate, cards: cards ?? [], unnamed: cards === null };
        setDetails(next);
        const iris = namedIris(next);
        if (iris.length)
          explorer
            .resolve(iris, controller.signal)
            .then(() => !controller.signal.aborted && setLabelEpoch((value) => value + 1))
            .catch(() => {});
      } catch {
        if (!controller.signal.aborted) setDetails({ ...EMPTY, status: "failed" });
      }
    })();
    return () => controller.abort();
    // The edge object changes with every layout frame; its statement is what matters.
  }, [edgeKey, endpoint, scope, explorer]);

  const labelOf = useCallback((iri: string) => explorer.label(iri), [explorer]);
  return { details, labelOf };
}
